const http = require('http');
const express = require('express');
const { WebSocketServer } = require('ws');
const { NotificationHub } = require('../notifications/hub');
const { verifyUserAuth } = require('../auth/user');

const app = express();
const server = http.createServer(app);
const wss = new WebSocketServer({ noServer: true });

server.on('upgrade', async (req, socket, head) => {
  const authUser = await verifyUserAuth(req);
  if (!authUser) {
    socket.write('HTTP/1.1 401 Unauthorized\r\n\r\n');
    socket.destroy();
    return;
  }

  const protocolHeader = req.headers['sec-websocket-protocol'] || '';
  const match = protocolHeader.match(/user\.client\.([a-zA-Z0-9_-]+)/);

  if (!match) {
    socket.destroy();
    return;
  }

  const declaredUserId = match[1];

  // Strictly verify that declared userId matches authenticated user ID
  if (declaredUserId !== authUser.id) {
    socket.write('HTTP/1.1 403 Forbidden\r\n\r\n');
    socket.destroy();
    return;
  }

  wss.handleUpgrade(req, socket, head, (ws) => {
    NotificationHub.registerClient(authUser.id, ws);
  });
});

server.listen(8082);
